select case when quantity >= 8 then 'PREMIUM' else 'STANDARD' end as quantity_tier, order_id, approx_percentile(unit_price, 0.95) as unit_price_p95, corr(unit_price, quantity) as corr_unit_price_quantity, count(distinct product_id) as distinct_product_ids, bit_and(quantity) as quantity_bit_and, approx_percentile(unit_price, 0.95) as unit_price_p95_2 from order_items group by case when quantity >= 8 then 'PREMIUM' else 'STANDARD' end, order_id order by quantity_bit_and desc nulls last;
